import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"交付路线与实施计划","description":"Hearth 的六个交付阶段：从最小完整 MVP 到可长期运行的个人 Agent OS。","frontmatter":{"title":"交付路线与实施计划","description":"Hearth 的六个交付阶段：从最小完整 MVP 到可长期运行的个人 Agent OS。","outline":[2,3]},"headers":[],"relativePath":"delivery/index.md","filePath":"delivery/index.md","lastUpdated":1795426969000}'),o={name:"delivery/index.md"};function h(s,t,n,l,i,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="交付路线与实施计划" tabindex="-1">交付路线与实施计划 <a class="header-anchor" href="#交付路线与实施计划" aria-label="Permalink to &quot;交付路线与实施计划&quot;">​</a></h1><p class="lead">这份路线只回答两件事：先做什么，后做什么；每个阶段怎样从可用走到可靠。</p><h2 id="总体目标" tabindex="-1">总体目标 <a class="header-anchor" href="#总体目标" aria-label="Permalink to &quot;总体目标&quot;">​</a></h2><p>Hearth 的目标是把个人数字工作变成可靠的任务。路线不从架构模块出发，而从用户能完成的事情出发：先交付一个最小完整产品，再逐步扩大工作范围、主动性、记忆和多设备能力。</p><h2 id="当前进展" tabindex="-1">当前进展 <a class="header-anchor" href="#当前进展" aria-label="Permalink to &quot;当前进展&quot;">​</a></h2><p>截至 2026-11-23，当前 <code>main</code> 是 <code>0.3.4</code>：单用户、本地优先的可信任务工作台已经收缩为聊天优先的控制面。聊天与普通/coding 任务、内联执行轨迹与产物面板、审批与效果账本、检查点与回退、浏览器自动化与证据、资料库/记忆/Context 交接、项目档案与工作方式、首次真实任务验证、自用报告和发布脚本形成代码与自动测试闭环；Windows 使用 AppContainer 原生沙箱、ConPTY 交互式 shell 与持久后台进程；服务端只写 SQLite 事件日志，<code>HostKernel</code> 管理宿主租约与阶段化恢复。</p><p>本机 <code>main</code> 验证：typecheck 0 错误、140 个测试文件 931 通过（946 总数，15 跳过）、长跑矩阵 18/18、Web 与文档构建通过；0.3.4 安装包（30.5 MiB）与便携包（47.2 MiB）已作为 Pre-release 发布。任务列表、任务详情和“需要你”收件箱已下线，执行轨迹改为对话内联运行卡；主导航为聊天、资料库、Context。</p><p>真实模型首跑仍取决于本机模型配置与供应商权限；自动更新签名、干净机安装/卸载、真实飞书/邮件账户、Windows 代码签名和数周长期运行仍未验收。详细证据和留空项见<a href="/hearth-os/delivery/status.html">当前交付状态</a>和<a href="/hearth-os/delivery/acceptance-2026-11.html">2026-11 验收报告</a>。下面的阶段页是历史路线，部分描述已不再代表当前范围。</p><h2 id="六个阶段" tabindex="-1">六个阶段 <a class="header-anchor" href="#六个阶段" aria-label="Permalink to &quot;六个阶段&quot;">​</a></h2><p>每个阶段都包含四个小阶段，点击阶段名称可以进入详细计划。</p><table tabindex="0"><thead><tr><th>阶段</th><th>目标</th><th>当前状态</th><th>完成后得到什么</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-1.html">第一阶段 · 最小完整 MVP</a></td><td>交付一个以 15 个跨行业真实任务为基线、至少通过 10 个的最小完整产品。</td><td><strong>已验收</strong>：15 个任务全部运行，13 个通过；T07、T08 保留为未完成边界</td><td>一个能每天使用、覆盖多个任务族的本地任务工作台</td></tr><tr><td><a href="/hearth-os/delivery/stage-2.html">第二阶段 · 日常内容工作</a></td><td>从首批跨行业任务扩展到邮件、日历、文档、表格和网页。</td><td><strong>部分完成</strong>：本地来源、文档提取、草稿审批、本地发件箱、SMTP 发送和 IMAP 只读同步代码闭环已跑通；真实账户和日历未验收</td><td>能处理日常内容并在审批后安全写入的个人操作员</td></tr><tr><td><a href="/hearth-os/delivery/stage-3.html">第三阶段 · 桌面操作</a></td><td>让 Hearth 操作没有开放接口的桌面软件和跨应用流程。</td><td><strong>部分完成</strong>：Windows 同机配对、观察、接管和白名单低风险操作已跑通；高风险与隔离未做</td><td>能操作桌面软件、可暂停、可接管、失败可恢复的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-4.html">第四阶段 · 主动服务与手机入口</a></td><td>在有限授权内主动工作，并把手机作为审批和接管入口。</td><td><strong>部分完成（历史）</strong>：触发、建议、注意力预算、PWA 壳和飞书长连接曾跑通；任务面收缩后收件箱已下线，手机配对、系统推送和远程接管未验收</td><td>能在合适时机提醒，并可在手机上审批和接管的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-5.html">第五阶段 · 记忆与能力进化</a></td><td>让系统积累背景并改进方法，但所有变化都可查看、可纠正、可回退。</td><td><strong>部分完成</strong>：记忆来源/合并/遗忘、技能生命周期、方法评估和持久委派代码闭环已跑通；真实长期使用与生产对照未完成</td><td>会积累背景、改进方法且可纠正可回退的助手</td></tr><tr><td><a href="/hearth-os/delivery/stage-6.html">第六阶段 · 多设备与长期运行</a></td><td>让同一套任务、记忆和授权在多台设备上长期安全使用。</td><td><strong>部分完成</strong>：同步、租约、撤销、备份、健康检查和连接运行时已跑通；真实双设备、远程节点与长期运行未验收</td><td>可多设备使用、可迁移、可长期运行的个人 Agent OS</td></tr></tbody></table><h2 id="怎么推进" tabindex="-1">怎么推进 <a class="header-anchor" href="#怎么推进" aria-label="Permalink to &quot;怎么推进&quot;">​</a></h2><ol><li><strong>先完整后扩展。</strong> 先把首批 15 个任务中的至少 10 个做完整，再增加新的信息来源、操作方式和设备。</li><li><strong>先只读后写入，先低风险后高风险。</strong> 每一类外部操作都先观察、再起草、再审批执行。</li><li><strong>每阶段都用真实任务验收。</strong> 不以代码写完或页面做完作为完成标准。</li><li><strong>安全和恢复从第一阶段就有。</strong> 审批、产物、失败恢复、权限边界不放到最后补。</li></ol><p>从<a href="/hearth-os/delivery/stage-1.html">第一阶段 · 最小完整 MVP</a>开始；阶段二至六的已实现范围与留空项统一记录在<a href="/hearth-os/delivery/status.html">交付状态</a>。</p>',14)])])}const m=e(o,[["render",h]]);export{p as __pageData,m as default};
